 apply=("Apply it: review your role-play", ["Record a role-play with permission.", "Time the talk share.", "Mark each principle in the checklist with an example.", "Mark every line you did not mean and rewrite it.", "Write three things to keep and three to change, and run it again."]),
 act="Record a role-play, mark it against the checklist and rewrite every line that was not sincere.",
 checks=[("Which is a Carnegie principle for winning people to your way of thinking?", ["The only way to get the best of an argument is to avoid it", "Interrupt often", "Never smile", "Talk about yourself"], 0, "It is the first of the twelve ways to win people to your way of thinking. {{carnegie-wiki}}"),
         ("What did the critics say the method risked?", ["Being too long", "Insincerity and manipulation", "Being too honest", "Being too slow"], 1, "Lewis and later scholars called it insincere and manipulative. {{carnegie-wiki}}"),
         ("In the example, the buyer spoke 5 of 12 minutes. What share is that?", ["25%", "42%", "50%", "58%"], 1, "5 ÷ 12 = 0.417.")],
